/**
 * prismaClient — creates the one Prisma client the server uses to talk to PostgreSQL.
 *
 * Why: Prisma 7 needs an explicit driver adapter; building the client in one place keeps the
 *      connection settings and pool size consistent for every repository and storage adapter.
 * Spec: H5P-004, DATA-001
 * Invariants:
 *   - Uses `@prisma/adapter-pg` (node-postgres); the URL comes from validated config (DATABASE_URL).
 *   - The caller owns the client and must `$disconnect()` it on shutdown.
 * Collaborators: ../generated/prisma (generated by `npm run db:generate`), ../config/env.ts,
 *   ../h5p/storage/PrismaContentStorage.ts.
 * Tests: apps/server/test/db/schema.int.test.ts
 */
import { PrismaPg } from '@prisma/adapter-pg';
import { PrismaClient } from '../generated/prisma/client.js';

/** The generated client type, re-exported so other modules need not import from `generated/`. */
export type Database = PrismaClient;

/**
 * Creates a Prisma client backed by a node-postgres pool.
 * @param databaseUrl - PostgreSQL connection string.
 * @returns A client; nothing connects until the first query.
 */
export function createPrismaClient(databaseUrl: string): Database {
  return new PrismaClient({ adapter: new PrismaPg({ connectionString: databaseUrl }) });
}
